tape( 'the function supports view offsets', function test( t ) {
	var expected;
	var x0;
	var x1;

	// Initial array...
	x0 = new Float64Array([
		1.0,
		2.0, // 0
		3.0, // 1
		4.0, // 2
		5.0, // 3
		6.0, // 4
		7.0,
		8.0
	]);

	// Create offset view...
	x1 = new Float64Array( x0.buffer, x0.BYTES_PER_ELEMENT*1 ); // begin at 2nd element

	gcopyWithin( 3, 0, 2, 5, x1, 1 );

	expected = new Float64Array( [ 1.0, 4.0, 5.0, 6.0, 5.0, 6.0, 7.0, 8.0 ] );

	t.deepEqual( x0, expected, 'returns expected value' );
	t.end();
});
